import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.vLhlLNVn.js";const i="/assets/preset-laden.BInGZmhv.svg",w=JSON.parse('{"title":"Using effects and presets","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/02.anleitungen/02.effekte-und-presets.md"},"headers":[],"relativePath":"adapter/wled/anleitungen/effekte-und-presets.md","filePath":"adapter/wled/anleitungen/effekte-und-presets.md","lastUpdated":null}'),r={name:"adapter/wled/anleitungen/effekte-und-presets.md"};function n(h,e,d,l,p,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="using-effects-and-presets" tabindex="-1">Using effects and presets <a class="header-anchor" href="#using-effects-and-presets" aria-label="Permalink to &quot;Using effects and presets&quot;">​</a></h1><p><a id="switch-wled-presets-via-ps"></a></p><h2 id="how-do-i-switch-wled-presets-via-the-state-ps-in-vis-blockly-or-a-script" tabindex="-1">How do I switch WLED presets via the state (ps) in VIS, Blockly or a script? <a class="header-anchor" href="#how-do-i-switch-wled-presets-via-the-state-ps-in-vis-blockly-or-a-script" aria-label="Permalink to &quot;How do I switch WLED presets via the state (ps) in VIS, Blockly or a script?&quot;">​</a></h2><p><strong>In short:</strong> Create the preset in the WLED web interface and write its number as a number to <code>wled.0.&lt;MAC&gt;.ps</code>, as a control command (<code>ack=false</code>). Whether the light turns on or off is decided by the preset itself, not by the adapter.</p><p>The adapter passes the value on to the device unchanged as <code>{&quot;ps&quot;:3}</code>, via WebSocket or HTTP. The presets themselves live only in WLED. The adapter knows their numbers but not their names, and it doesn&#39;t create a list of presets.</p><h3 id="which-presets-you-need" tabindex="-1">Which presets you need <a class="header-anchor" href="#which-presets-you-need" aria-label="Permalink to &quot;Which presets you need&quot;">​</a></h3><ol><li>Open the WLED web interface of the device in your browser and set color, effect and brightness the way the preset should look.</li><li>Save the state with &quot;Create Preset&quot;. The number under &quot;Save to ID&quot; is the number you will later write to <code>ps</code>. Allowed values are 1 to 250.</li><li>When saving, decide whether &quot;Include brightness&quot; should be on. This determines whether the preset switches the light on or off (see below).</li></ol><h3 id="how-to-set-ps" tabindex="-1">How to set ps <a class="header-anchor" href="#how-to-set-ps" aria-label="Permalink to &quot;How to set ps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>How</th></tr></thead><tbody><tr><td>Object tree in Admin</td><td>Enter the number at <code>wled.0.&lt;MAC&gt;.ps</code> and save.</td></tr><tr><td>JavaScript</td><td><code>setState(&#39;wled.0.&lt;MAC&gt;.ps&#39;, 3);</code> (without a third argument this is a control command)</td></tr><tr><td>Blockly</td><td>The &quot;control&quot; block with the object <code>ps</code> and the number as value. Don&#39;t use &quot;update&quot;.</td></tr><tr><td>VIS</td><td>A widget that writes a fixed value, for example a button with the preset number, or a drop-down list with the preset numbers as values and the names as texts.</td></tr></tbody></table><p>The adapter only sends values with <code>ack=false</code> to the device. A value with <code>ack=true</code> (&quot;update&quot; in Blockly) counts as feedback from the device and is not sent.</p><p><code>ps</code> is a state of type number. So write <code>3</code>, not <code>&quot;3&quot;</code>. WLED does understand the text as well, but ioBroker then logs a warning about the wrong data type.</p><p>If it worked, <code>ps</code> shortly afterwards shows the number the device reports back. If you then change something by hand in WLED, WLED reports <code>-1</code>, because no preset is active any more.</p><h3 id="why-does-the-light-turn-on-or-off-when-the-preset-changes" tabindex="-1">Why does the light turn on or off when the preset changes? <a class="header-anchor" href="#why-does-the-light-turn-on-or-off-when-the-preset-changes" aria-label="Permalink to &quot;Why does the light turn on or off when the preset changes?&quot;">​</a></h3><p>With &quot;Include brightness&quot;, a preset also stores the on/off state and the brightness at the moment you saved it. If it was saved while the light was off, it switches the light off when called. If it was saved while the light was on, it switches the light on. Without &quot;Include brightness&quot; the light stays as it is, so it also stays off if it was off before.</p><p><img src="'+i+'" alt="What happens when ps is set: if the number is already active, nothing happens. Otherwise WLED loads the preset, and &quot;Include brightness&quot; decides on/off and brightness."></p><p>This is how you get the behavior you want:</p><ul><li><strong>The preset should always switch on:</strong> save the preset again with the light on and with &quot;Include brightness&quot;.</li><li><strong>The preset should only change effect and color:</strong> save it without &quot;Include brightness&quot; and switch the light separately via <code>wled.0.&lt;MAC&gt;.on</code>.</li><li><strong>Switch on and load a preset in one command:</strong> write <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> to the state <code>wled.0.&lt;MAC&gt;.action</code>. WLED evaluates <code>on</code> before <code>ps</code>.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>WLED doesn&#39;t load a preset again if it is already the active preset. This also applies if you switched the light off via <code>on</code> in between: <code>ps</code> still shows the same number, and writing the same number again does nothing. In that case, switch on with <code>on</code> or send <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> via <code>action</code>.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>To save the current state as a preset from ioBroker, write the number you want to <code>wled.0.&lt;MAC&gt;.psave</code>.</p></div><p><strong>See also:</strong> <a href="./skripte#switch-wled-presets-automatically-example">Switch presets with a motion sensor</a> · <a href="#step-through-presets-button-script">Step through presets one after another</a> · <a href="#start-wled-playlist-through-adapter">Start a playlist</a> · <a href="./../fehlerbehebung/befehle-wirken-nicht#script-not-ps-wled-ignores">Script doesn&#39;t set ps or on</a> · <a href="./../fehlerbehebung/befehle-wirken-nicht#ps-jump-1-not-show">ps jumps to -1</a></p><p><a id="step-through-presets-button-script"></a></p><h2 id="how-do-i-step-through-presets-one-after-another-with-a-button-or-a-script" tabindex="-1">How do I step through presets one after another with a button or a script? <a class="header-anchor" href="#how-do-i-step-through-presets-one-after-another-with-a-button-or-a-script" aria-label="Permalink to &quot;How do I step through presets one after another with a button or a script?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="start-wled-playlist-through-adapter"></a></p><h2 id="how-do-i-start-a-wled-playlist-through-the-adapter" tabindex="-1">How do I start a WLED playlist through the adapter? <a class="header-anchor" href="#how-do-i-start-a-wled-playlist-through-the-adapter" aria-label="Permalink to &quot;How do I start a WLED playlist through the adapter?&quot;">​</a></h2><p><strong>In short:</strong> In WLED, a playlist is a preset with its own number. So you start it like any preset, by writing its number to <code>wled.0.&lt;MAC&gt;.ps</code>. The state <code>pl</code> only shows which playlist is currently running. Writing to it doesn&#39;t start a playlist.</p><h3 id="start-a-playlist-via-ps" tabindex="-1">Start a playlist via ps <a class="header-anchor" href="#start-a-playlist-via-ps" aria-label="Permalink to &quot;Start a playlist via ps&quot;">​</a></h3><ol><li>Create the playlist in the WLED web interface. When you save it, it gets a number like any preset. </li><li>Write this number to <code>wled.0.&lt;MAC&gt;.ps</code>, for example in JavaScript with <code>setState(&#39;wled.0.&lt;MAC&gt;.ps&#39;, 9);</code> or in Blockly with &quot;control&quot;.</li><li>While the playlist is running, <code>pl</code> shows its number and <code>ps</code> the preset from it that is currently active. If no playlist is running, <code>pl</code> shows the value <code>-1</code>.</li></ol><p>How <code>ps</code> works in detail is described under <a href="#switch-wled-presets-via-ps">Switch presets via the ps state</a>.</p><h3 id="start-a-playlist-without-a-saved-preset-via-action" tabindex="-1">Start a playlist without a saved preset via action <a class="header-anchor" href="#start-a-playlist-without-a-saved-preset-via-action" aria-label="Permalink to &quot;Start a playlist without a saved preset via action&quot;">​</a></h3><p>Through the state <code>wled.0.&lt;MAC&gt;.action</code> you can also send a playlist directly as JSON, without saving it in WLED first. This example shows presets 1, 2 and 3 for 30 seconds each, repeats this endlessly and switches the light on:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;playlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ps&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dur&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;transition&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;repeat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ps</code></td><td>The preset numbers in the order they should run</td></tr><tr><td><code>dur</code></td><td>How long each preset stays, in tenths of a second (<code>300</code> = 30 seconds)</td></tr><tr><td><code>transition</code></td><td>Transition time to the next preset, in tenths of a second</td></tr><tr><td><code>repeat</code></td><td>How often the whole playlist runs; <code>0</code> means endlessly</td></tr><tr><td><code>end</code></td><td>Preset loaded after the last run; has no effect with <code>repeat</code> = <code>0</code></td></tr></tbody></table><h3 id="advance-or-stop-a-playlist" tabindex="-1">Advance or stop a playlist <a class="header-anchor" href="#advance-or-stop-a-playlist" aria-label="Permalink to &quot;Advance or stop a playlist&quot;">​</a></h3><ul><li><strong>Jump to the next preset:</strong> send <code>{&quot;np&quot;:true}</code> to <code>action</code>. This is available from WLED firmware 0.15.</li><li><strong>Stop:</strong> set another preset via <code>ps</code> or change a segment directly, for example the effect. That ends the playlist.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The adapter creates <code>pl</code> as a writable state. However, WLED ignores a written value; the WLED JSON API lists <code>pl</code> as &quot;read-only&quot;. So use <code>ps</code> or <code>action</code> to start a playlist.</p></div><p><strong>See also:</strong> <a href="#step-through-presets-button-script">Step through presets one after another</a> · <a href="./befehle-an-wled#send-complete-json-command-wled">Send a complete JSON command</a></p><p><a id="numbers-names-effects-palettes-scripts"></a></p><h2 id="where-do-i-find-the-numbers-and-names-of-effects-and-palettes-for-scripts" tabindex="-1">Where do I find the numbers and names of effects and palettes for scripts? <a class="header-anchor" href="#where-do-i-find-the-numbers-and-names-of-effects-and-palettes-for-scripts" aria-label="Permalink to &quot;Where do I find the numbers and names of effects and palettes for scripts?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="control-percent-effect-show-value"></a></p><h2 id="how-do-i-control-the-percent-effect-and-show-a-value-as-a-bar" tabindex="-1">How do I control the &quot;Percent&quot; effect and show a value as a bar? <a class="header-anchor" href="#how-do-i-control-the-percent-effect-and-show-a-value-as-a-bar" aria-label="Permalink to &quot;How do I control the &quot;Percent&quot; effect and show a value as a bar?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="change-text-scrolling-text-effect"></a></p><h2 id="how-do-i-change-the-text-of-the-scrolling-text-effect-or-the-segment-name" tabindex="-1">How do I change the text of the &quot;Scrolling Text&quot; effect or the segment name? <a class="header-anchor" href="#how-do-i-change-the-text-of-the-scrolling-text-effect-or-the-segment-name" aria-label="Permalink to &quot;How do I change the text of the &quot;Scrolling Text&quot; effect or the segment name?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="effect-palette-survive-power-loss"></a></p><h2 id="how-do-effect-and-palette-survive-a-power-loss-and-how-does-wled-start-afterwards" tabindex="-1">How do effect and palette survive a power loss, and how does WLED start afterwards? <a class="header-anchor" href="#how-do-effect-and-palette-survive-a-power-loss-and-how-does-wled-start-afterwards" aria-label="Permalink to &quot;How do effect and palette survive a power loss, and how does WLED start afterwards?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',49)])])}const f=t(r,[["render",n]]);export{w as __pageData,f as default};
